package org.mockito;

import java.util.function.Supplier;
import java.util.*;

public class Mockito {
   public static <T> T mock(Class<T> clazz) {
       if (CompositeURITranslator.class.isAssignableFrom(clazz)) {
           return (T) new SimpleComposite();
       }
       if (URITranslator.class.isAssignableFrom(clazz)) {
           return (T) new SimpleURITranslator(Collections.emptyMap());
       }
       // generic proxy returning default values
       return java.lang.reflect.Proxy.newProxyInstance(clazz.getClassLoader(),
               new Class[]{clazz},
               (proxy, method, args) -> {
                   Class<?> ret = method.getReturnType();
                   if (ret.isPrimitive()) {
                       if (ret == boolean.class) return false;
                       if (ret == byte.class) return (byte)0;
                       if (ret == short.class) return (short)0;
                       if (ret == int.class) return 0;
                       if (ret == long.class) return 0L;
                       if (ret == float.class) return 0f;
                       if (ret == double.class) return 0d;
                       if (ret == char.class) return '\0';
                   }
                   return null;
               });
   }

   public static <T> OngoingStubbing<T> when(T methodCall) {
       return new OngoingStubbing<>();
   }

   public static <T> T any(Class<T> clazz) {
       return null;
   }

   public static <T> Verifier<T> verify(T mock) {
       return new Verifier<>();
   }

   public static <T> MockedStatic<T> mockStatic(Class<T> clazz) {
       return new MockedStatic<>();
   }
}

class OngoingStubbing<T> {
   public T thenReturn(T value) { return value; }
}

class Verifier<T> {
   public void with(Object arg) {}
}

class MockedStatic<T> {
   public <R> OngoingStubbing<R> when(Supplier<R> supplier) { return new OngoingStubbing<>(); }
   public void close() {}
}

